\set ON_ERROR_STOP on
do $$begin if current_database()<>'byus_clean'or inet_server_addr()is not null then raise exception 'Disposable Unixsocket byus_clean required';end if;end $$;
begin;
create function pg_temp.gift_assert(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',message;end if;raise notice 'PASS %',message;end $$;
create function pg_temp.gift_error(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then return;end if;raise;end;raise exception 'Expected %',expected;end $$;
do $$declare owner uuid:=gen_random_uuid();member uuid:=gen_random_uuid();admin_actor uuid:=gen_random_uuid();admin uuid:=gen_random_uuid();viewer_actor uuid:=gen_random_uuid();viewer uuid:=gen_random_uuid();page uuid:=gen_random_uuid();other_page uuid:=gen_random_uuid();image uuid:=gen_random_uuid();image2 uuid:=gen_random_uuid();gift uuid;raffle uuid;input jsonb;review jsonb;create_input jsonb;receipt jsonb;saved jsonb;begin
 insert into public.app_users(id,privy_user_id,verified_email)values(owner,'gift-owner-'||owner,owner||'@example.test'),(member,'gift-member-'||member,member||'@example.test'),(admin_actor,'gift-admin-'||admin_actor,admin_actor||'@example.test'),(viewer_actor,'gift-viewer-'||viewer_actor,viewer_actor||'@example.test');
 insert into public.admin_allowlist(id,email,role)values(admin,admin_actor||'@example.test','operator'),(viewer,viewer_actor||'@example.test','viewer');
 insert into public.group_pages(id,kind,name)values(page,'hobby','Gift fixture'),(other_page,'hobby','Other page');
 insert into public.group_memberships(page_id,app_user_id,role)values(page,owner,'owner'),(page,member,'member'),(other_page,owner,'owner');
 update public.group_wallet_release set enabled=true,write_fenced=false,legacy_writers_verified=true,migration_evidence_sha256=repeat('a',64),rewards_start_on=current_date;
 insert into public.mobile_media_assets(id,app_user_id,kind,purpose,content_type,expected_byte_size,actual_byte_size,storage_path,thumbnail_path,state,width,height,request_id,request_hash)select x,owner,'image','group_image','image/png',100,100,'private/'||x||'.png','private/'||x||'.webp','ready',20,20,gen_random_uuid(),'fixture'from unnest(array[image,image2])x;
 input:=jsonb_build_object('requestId',gen_random_uuid(),'name','Approved gift','imageAssetId',image,'quantity',10,'providerName','Fixture provider','fulfillmentMethod','on_site_pickup','fulfillmentDescription','At venue','conditions','Members only');
 receipt:=public.group_gifts_dispatch('submit',owner,page,null,input);gift:=(receipt->>'id')::uuid;
 perform pg_temp.gift_assert(receipt=public.group_gifts_dispatch('submit',owner,page,null,input),'submission retry reuses one application');
 perform pg_temp.gift_assert(public.authorize_group_image_read(null,image,'original')is null and public.authorize_mobile_media_read(member,image,'original')is null,'pending gift is private through both image entrypoints');
 perform pg_temp.gift_assert(public.authorize_mobile_media_read(owner,image,'original')is not null and public.authorize_mobile_media_read(admin_actor,image,'original')is not null,'operator and active reviewer can read pending image');
 perform pg_temp.gift_error(format('select public.group_gifts_dispatch(''submit'',%L,%L,null,%L)',member,page,input),'FORBIDDEN');
 review:=jsonb_build_object('requestId',gen_random_uuid(),'expectedRevision',1,'decision','approved','reason','');
 perform pg_temp.gift_error(format('select public.group_gifts_dispatch(''review'',%L,null,%L,%L,%L)',viewer_actor,gift,review,viewer),'read-only');
 receipt:=public.group_gifts_dispatch('review',admin_actor,null,gift,review,admin);
 perform pg_temp.gift_assert(receipt=public.group_gifts_dispatch('review',admin_actor,null,gift,review,admin),'successful approval replay survives revision increment');
 perform pg_temp.gift_assert(public.authorize_group_image_read(null,image,'original')is null,'approval alone never publishes image');
 perform pg_temp.gift_error(format('select public.group_gifts_dispatch(''review'',%L,null,%L,%L,%L)',admin_actor,gift,review||jsonb_build_object('requestId',gen_random_uuid()),admin),'CONFLICT');
 create_input:=jsonb_build_object('requestId',gen_random_uuid(),'giftApplicationId',gift,'title','FORGED','imageUrl','https://evil.test/image','summary','FORGED','winnerQuantity',6,'perUserLimit',2,'closesAt',clock_timestamp()+interval '1 day','submissionDays',7,'fulfillmentMethod','digital');
 perform pg_temp.gift_error(format('select public.group_raffle_dispatch(''create'',%L,%L,null,%L)',owner,other_page,create_input),'NOT_FOUND');
 receipt:=public.group_raffle_dispatch('create',owner,page,null,create_input);raffle:=(receipt->>'id')::uuid;
 perform pg_temp.gift_assert(receipt=public.group_raffle_dispatch('create',owner,page,null,create_input),'gift-backed raffle create is idempotent');
 perform pg_temp.gift_assert((select title='Approved gift'and image_url='/api/groups/images/'||image::text and fulfillment_method='on_site_pickup'and summary='Members only'from public.group_raffles where id=raffle),'published fields are derived from approved gift');
 perform pg_temp.gift_assert(public.authorize_group_image_read(null,image,'original')is not null and public.authorize_mobile_media_read(member,image,'original')is not null,'published linked raffle grants public image ACL');
 perform pg_temp.gift_error(format('select public.group_raffle_dispatch(''create'',%L,%L,null,%L)',owner,page,create_input||jsonb_build_object('requestId',gen_random_uuid(),'winnerQuantity',5)),'STOCK');
 perform pg_temp.gift_assert((public.group_gift_json(gift)->>'availableQuantity')::integer=4,'live remaining stock excludes reserved winners');
 perform pg_temp.gift_error(format('update public.group_raffles set title=''Forged''where id=%L',raffle),'CONFLICT');
 perform public.group_gifts_dispatch('review',admin_actor,null,gift,jsonb_build_object('requestId',gen_random_uuid(),'expectedRevision',2,'decision','changes_requested','reason','Update provider'),admin);
 saved:=(select gift_snapshot from public.group_raffles where id=raffle);
 input:=(input-'requestId')||jsonb_build_object('requestId',gen_random_uuid(),'expectedRevision',3,'name','Revised gift','imageAssetId',image2);
 perform public.group_gifts_dispatch('revise',owner,page,gift,input);
 perform pg_temp.gift_assert((select gift_snapshot=saved from public.group_raffles where id=raffle)and public.authorize_group_image_read(null,image,'original')is not null and(select state='ready'from public.mobile_media_assets where id=image),'resubmission keeps old immutable snapshot image alive');
 perform pg_temp.gift_assert(public.authorize_group_image_read(null,image2,'original')is null,'new pending revision image remains private');
 perform pg_temp.gift_assert(jsonb_array_length(public.group_gifts_dispatch('detail',owner,page,gift)->'history')=4,'review and submission history remains append only');
 perform pg_temp.gift_error(format('update public.group_gift_history set reason=''overwrite''where application_id=%L',gift),'CONFLICT');
 update public.group_memberships set role='member'where page_id=page and app_user_id=owner;
 perform pg_temp.gift_error(format('select public.group_gifts_dispatch(''detail'',%L,%L,%L)',owner,page,gift),'FORBIDDEN');
 perform pg_temp.gift_assert(public.authorize_group_image_read(owner,image2,'original')is null,'former operator loses pending image access');
 perform pg_temp.gift_assert(not has_table_privilege('service_role','public.group_gift_applications','SELECT')and not has_function_privilege('authenticated','public.group_gifts_dispatch(text,uuid,uuid,uuid,jsonb,uuid)','EXECUTE')and not has_function_privilege('service_role','public.group_raffle_dispatch_before_gifts(text,uuid,uuid,uuid,jsonb,uuid)','EXECUTE'),'raw rows and delegated bypass entrypoints are private');
end $$;
rollback;
